```js
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const Dx = ball.x - prevX;
  const Dy = ball.y - prevY;
  const total = Math.hypot(Dx, Dy);
  const dirX = total > 0 ? Dx / total : 0;
  const dirY = total > 0 ? Dy / total : 0;
  const stepLen = 2 * ball.r;
  let remaining = total;

  do {
    const sub = Math.min(remaining, stepLen);
    if (total > 0) { ball.x += dirX * sub; ball.y += dirY * sub; }
    remaining -= sub;

    // Gather overlapping live bricks at this position.
    const hit = state.bricks.filter(b => b.alive && collides(ball, b));
    if (hit.length > 0) {
      // Primary face = the brick the ball penetrated least (closest surface).
      let primary = hit[0];
      let bestPen = Infinity;
      for (const b of hit) {
        const pen = Math.min(
          ball.x + ball.r - b.x,
          b.x + b.w - (ball.x - ball.r),
          ball.y + ball.r - b.y,
          b.y + b.h - (ball.y - ball.r)
        );
        if (pen < bestPen) { bestPen = pen; primary = b; }
      }
      // Break every touched brick but bounce exactly once.
      for (const b of hit) {
        b.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(b, state.combo);
      }
      resolveBounce(ball, primary);
      break; // one bounce per frame
    }
  } while (remaining > 0);
}
```

