// Sweeps the ball from where it was before the last step() to where it now is,
// in sub-steps no larger than a ball diameter. A single frame can move the
// ball far enough (35.5 px at level 6) to skip over a 34 px brick (BRICK_H +
// diameter) in one discrete jump — sub-stepping the sweep catches it, so the
// ball can never tunnel through.
//
// Bricks overlap at the seams (grid gap 8 px < ball diameter 14 px), so a
// single ball can straddle two bricks at once. Every overlapping brick is
// broken and scored, but the velocity bounce is applied EXACTLY ONCE — a naive
// per-brick `vy = -vy` would flip twice and cancel out, letting the ball
// through. Returns nothing; mutates `state` (bricks, combo, score, ball).
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const total = Math.hypot(dx, dy);
  const dirX = total > 0 ? dx / total : 0;
  const dirY = total > 0 ? dy / total : 0;
  const subLen = 2 * ball.r;
  let remaining = total;

  do {
    // Advance one sub-step along the swept segment.
    const sub = Math.min(remaining, subLen);
    if (total > 0) {
      ball.x += dirX * sub;
      ball.y += dirY * sub;
    }
    remaining -= sub;

    // Every live brick the ball touches at this sub-step.
    const hit = [];
    for (const brick of state.bricks) {
      if (brick.alive && collides(ball, brick)) hit.push(brick);
    }
    if (hit.length === 0) continue;

    // Break and score each touched brick...
    for (const brick of hit) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }

    // ...but bounce exactly once, off the face the ball has penetrated least.
    let primary = hit[0];
    let bestPen = Infinity;
    for (const brick of hit) {
      const pen = Math.min(
        ball.x + ball.r - brick.x,
        brick.x + brick.w - (ball.x - ball.r),
        ball.y + ball.r - brick.y,
        brick.y + brick.h - (ball.y - ball.r)
      );
      if (pen < bestPen) {
        bestPen = pen;
        primary = brick;
      }
    }
    resolveBounce(ball, primary);
    return; // one bounce per frame is enough; the ball is now pushed clear
  } while (remaining > 0);
}
```

