edits.newText:
test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- #1: brick bounce ------------------------------------------------------

const BRICK = { x: 100, y: 100, w: 72, h: 20, row: 1, points: 100 };

// 1. Per face — a ball climbing into the brick from below hits the BOTTOM face:
//    the ball is pushed out below the brick and `vy` is reflected (becomes
//    DOWN / positive). `vx` is left exactly as it was.
test('bounce: head-on from below flips vy only, vx unchanged', () => {
  const s = bounceBall({
    x: 136, y: 124, prevX: 136, prevY: 126,
    vx: 0, vy: -100, brick: BRICK,
  });
  assert.equal(s.ball.vy, 100, 'vy reflected from UP to DOWN');
  assert.equal(s.ball.vx, 0, 'vx left untouched');
});

// 1b. Side hit — ball coming from the right hits the RIGHT face: `vx` is
//     reflected (now LEFT), while `vy` keeps its value.
test('bounce: side hit flips vx only, vy unchanged', () => {
  const s = bounceBall({
    x: 178, y: 110, prevX: 180, prevY: 110,
    vx: -50, vy: 42, brick: BRICK,
  });
  assert.equal(s.ball.vx, -50, 'vx reflected to the left (away from brick)');
  assert.equal(s.ball.vy, 42, 'vy left untouched');
});

// 1c. Corner — equal penetration on both axes flips BOTH components.
test('bounce: corner (equal penetration) flips both components', () => {
  const s = bounceBall({
    x: 102, y: 103, prevX: 102, prevY: 103,
    vx: 50, vy: 50, brick: BRICK,
  });
  assert.equal(s.ball.vx, -50, 'vx reflected to the left');
  assert.equal(s.ball.vy, -50, 'vy reflected upward');
  assert.equal(s.ball.x, BRICK.x - 7, 'pushed out to the left');
  assert.equal(s.ball.y, BRICK.y - 7, 'pushed out above');
});

// 2. Push out — after the bounce the ball must no longer overlap the brick,
//    otherwise it re-flips forever (sticky bounce).
test('bounce: ball is pushed out (no leftover overlap)', () => {
  const s = bounceBall({
    x: 136, y: 124, prevX: 136, prevY: 126,
    vx: 0, vy: -100, brick: BRICK,
  });
  assert.ok(!collides(s.ball, s.bricks[0]), 'ball and brick no longer overlap');
  assert.equal(s.bricks[0].alive, false, 'the brick was broken');
});

// 3. Neighbours — the ball straddles the seam between two side-by-side bricks
//    (grid gap 8 px < 14 px ball). Both bricks break, but the bounce is applied
//    EXACTLY ONCE: a double `vy = -vy` would cancel and let the ball through.
test('bounce: seam hit breaks both bricks but bounces exactly once', () => {
  const state = createState(1);
  const a = { ...BRICK, alive: true };
  const b = { ...BRICK, x: 180, alive: true };
  state.bricks = [a, b];
  state.ball.prevX = 176;
  state.ball.prevY = 125;
  state.ball = {
    ...state.ball, x: 176, y: 125, r: 7,
    vx: 0, vy: -100, prevX: 176, prevY: 125,
  };
  frame(mockCtx(), state);

  assert.equal(a.alive, false, 'first brick broken');
  assert.equal(b.alive, false, 'second brick broken');
  assert.equal(state.ball.vy, 100, 'vy flipped exactly once (not cancelled)');
  assert.ok(!collides(state.ball, a) && !collides(state.ball, b), 'pushed clear');
});

// 4. Tunnelling — two discrete positions on either side of a brick both miss
//    it (35.5 px/frame at level 6 vs ~34 px across), but the swept sub-steps
//    catch it. Endpoint-only detection (the old bug) lets it through.
test('bounce: fast ball is swept through the brick (no tunnelling)', () => {
  const s = bounceBall({
    x: 136, y: 80, prevX: 136, prevY: 140,
    vx: 0, vy: -10, brick: BRICK,
  });
  assert.equal(s.bricks[0].alive, false, 'brick caught mid-flight');
  assert.equal(s.ball.vy, 10, 'vy reflected after the swept hit');
});

// The old implementation checked only the final position: a ball that ended up
// on the far side of a brick reported no collision. Prove the sweep matters.
test('tunnelling: endpoint alone would NOT have collided', () => {
  const ball = { x: 136, y: 80, r: 7 };
  assert.equal(collides(ball, BRICK), false, 'final position misses the brick');
});

// Score & combo are wired up through the bounce path.
test('bounce breaks a brick and awards the combo score', () => {
  const s = bounceBall({
    x: 136, y: 124, prevX: 136, prevY: 126,
    vx: 0, vy: -100, brick: BRICK,
  });
  assert.equal(s.combo, 1);
  assert.ok(s.score > 0, `score increased (got ${s.score})`);
});

